<?php
/**
 * Theme bootstrap: loads inc/ and registers the theme hooks.
 *
 * - Setup: theme supports and the "primary" menu location, used by the
 *   fixed bottom navigation (footer.php). Menu item icons come from a CSS
 *   class "icon-<tabler-name>" on each item.
 * - Assets: dist/styles.css and dist/script.js, generated by webpack
 *   (npm run build). Their version is the file mtime (cache busting), or
 *   null when not built yet. The script loads deferred in the footer.
 *   Fonts are registered in theme.json and printed by WordPress itself.
 * - Classic editor: the block editor is disabled for every post type and
 *   for widgets. Existing block content still renders on the front end;
 *   in the editor it shows as HTML with block comments.
 * - Preloads: assets visible on first paint (body and heading fonts, and
 *   the background texture of styles/parts/background.css) are fetched
 *   before the CSS is parsed. Keep this list short.
 * - Custom registration and login: wp-login.php?action=register redirects
 *   to /register, the registration form (page-register.php) is handled on
 *   init, and after logging in administrators go to the dashboard and
 *   everyone else to the home page.
 */

require_once get_template_directory() . '/inc/template-tags.php';
require_once get_template_directory() . '/inc/images.php';
require_once get_template_directory() . '/inc/blocks.php';
require_once get_template_directory() . '/inc/class-navigation-walker.php';

function wordpress_classic_template_setup() {
    add_theme_support('title-tag');
    add_theme_support('post-thumbnails');
    add_theme_support('html5', array('search-form', 'comment-form', 'comment-list', 'gallery', 'caption', 'style', 'script'));

    register_nav_menus(array(
        'primary' => __('Bottom navigation', 'wordpress-classic-template'),
    ));
}
add_action('after_setup_theme', 'wordpress_classic_template_setup');

function wordpress_classic_template_asset_version($relative_path) {
    $file = get_template_directory() . $relative_path;
    return file_exists($file) ? filemtime($file) : null;
}

function wordpress_classic_template_enqueue_assets() {
    $uri = get_template_directory_uri();

    wp_enqueue_style('wordpress-classic-template-styles', $uri . '/dist/styles.css', array(), wordpress_classic_template_asset_version('/dist/styles.css'));

    wp_enqueue_script('wordpress-classic-template-script', $uri . '/dist/script.js', array(), wordpress_classic_template_asset_version('/dist/script.js'), array(
        'in_footer' => true,
        'strategy'  => 'defer',
    ));
}
add_action('wp_enqueue_scripts', 'wordpress_classic_template_enqueue_assets');

add_filter('use_block_editor_for_post_type', '__return_false', 100);
add_filter('use_widgets_block_editor', '__return_false');

function wordpress_classic_template_preload_assets() {
    $uri = get_template_directory_uri();

    $fonts = array(
        '/assets/fonts/poppins/poppins-latin-400-normal.woff2',
        '/assets/fonts/roboto-slab/roboto-slab-latin-wght-normal.woff2',
    );
    foreach ($fonts as $font) {
        printf(
            '<link rel="preload" href="%s" as="font" type="font/woff2" crossorigin>' . "\n",
            esc_url($uri . $font)
        );
    }

    printf(
        '<link rel="preload" href="%s" as="image" type="image/webp" fetchpriority="high">' . "\n",
        esc_url($uri . '/assets/images/noisy.webp')
    );
}
add_action('wp_head', 'wordpress_classic_template_preload_assets', 1);

function redirect_register_page() {
    if (isset($_GET['action']) && $_GET['action'] === 'register' && !is_user_logged_in()) {
        wp_redirect(site_url('/register'));
        exit;
    }
}
add_action('login_form_register', 'redirect_register_page');

function handle_custom_registration() {
    if (isset($_POST['register'])) {
        $errors = [];
        $first_name = sanitize_text_field($_POST['first_name']);
        $last_name = sanitize_text_field($_POST['last_name']);
        $user_login = sanitize_user($_POST['user_login']);
        $user_email = sanitize_email($_POST['user_email']);
        $password = $_POST['password'];
        $confirm_password = $_POST['confirm_password'];

        if (empty($first_name) || empty($last_name) || empty($user_login) || empty($user_email) || empty($password) || empty($confirm_password)) {
            $errors[] = __('All fields are required.', 'wordpress-classic-template');
        }
        if (!is_email($user_email)) {
            $errors[] = __('Invalid email address.', 'wordpress-classic-template');
        }
        if (username_exists($user_login)) {
            $errors[] = __('Username already exists.', 'wordpress-classic-template');
        }
        if (email_exists($user_email)) {
            $errors[] = __('Email is already registered.', 'wordpress-classic-template');
        }
        if ($password !== $confirm_password) {
            $errors[] = __('Passwords do not match.', 'wordpress-classic-template');
        }

        if (empty($errors)) {
            $user_id = wp_create_user($user_login, $password, $user_email);
            if (!is_wp_error($user_id)) {
                update_user_meta($user_id, 'first_name', $first_name);
                update_user_meta($user_id, 'last_name', $last_name);
                wp_redirect(site_url('/login?registered=1'));
                exit;
            } else {
                $errors[] = __('An error occurred while creating your account. Please try again.', 'wordpress-classic-template');
            }
        }

        global $registration_errors;
        $registration_errors = $errors;
    }
}
add_action('init', 'handle_custom_registration');

function custom_login_redirect($redirect_to, $request, $user) {
    if (isset($user->roles) && is_array($user->roles)) {
        if (in_array('administrator', $user->roles)) {
            return admin_url();
        } else {
            return site_url('/');
        }
    }
    return $redirect_to;
}
add_filter('login_redirect', 'custom_login_redirect', 10, 3);
